// Universal backtracking template
// Works for subsets, combinations, permutations with small tweaks

function backtrackingTemplate(nums) {
  const result = [];
  const path = [];

  function backtrack(start) {
    // Base case: valid complete solution - record a COPY, not reference
    result.push([...path]);

    // Loop over choices (start=0 for permutations, start=start for combinations)
    for (let i = start; i < nums.length; i++) {
      // Prune: skip if this choice violates constraints
      // (e.g., duplicate: if i > start && nums[i] === nums[i-1]) continue;

      path.push(nums[i]);     // make choice
      backtrack(i + 1);       // recurse (use i+1 for combinations, 0 for permutations)
      path.pop();             // UNDO choice - this is what makes it backtracking
    }
  }

  // nums.sort((a, b) => a - b); // sort first if need to skip duplicates
  backtrack(0);
  return result;
}

// Permutations variant: loop from 0, track used elements
function permutations(nums) {
  const result = [];
  const path = [];
  const used = new Array(nums.length).fill(false);

  function backtrack() {
    if (path.length === nums.length) {
      result.push([...path]);
      return;
    }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue;   // skip already placed elements
      path.push(nums[i]);
      used[i] = true;
      backtrack();
      path.pop();
      used[i] = false;         // undo
    }
  }

  backtrack();
  return result;
}
